-- V47 — Seed standard HR attestation templates (new visual design)
-- Migrates the 5 hardcoded HTML files from pdf-service/templates/arx/ into the
-- document_templates table so admins can view and edit them via "Maquettes documents".
-- DB-first: PdfDocumentService calls renderByName() and falls back to the old Node.js
-- path only when no active row is found.  This INSERT is idempotent: it skips any
-- pays+name combination that already exists.
-- Visual design: ARX logo header, Georgia serif body, centered bold title with underline,
-- right-aligned signature, footer with separator line.

-- ── 1. Attestation de Travail ─────────────────────────────────────────────
INSERT INTO [dbo].[document_templates]
    ([pays_id],[category],[name],[description],[html_content],[variables],[page_size],[is_active],[created_at])
SELECT
    p.id,
    N'ATTESTATION',
    N'Attestation de Travail',
    N'Attestation de travail standard (CDI/CDD)',
    N'<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { font-family: Georgia, ''Times New Roman'', Times, serif; font-size: 11pt; color: #000; } .page { width: 210mm; min-height: 297mm; padding: 18mm 22mm 30mm; position: relative; background: #fff; } .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12mm; } .arx-logo-text { font-family: Arial, Helvetica, sans-serif; font-size: 30pt; font-weight: 900; color: #1e3a5f; line-height: 1; letter-spacing: -1px; } .arx-tagline { font-family: Arial, Helvetica, sans-serif; font-size: 6.5pt; color: #666; letter-spacing: 4px; margin-top: 2mm; } .company-block { text-align: right; } .company-name-hdr { font-family: Arial, Helvetica, sans-serif; font-size: 11pt; font-weight: bold; color: #1e3a5f; } .company-sub { font-family: Arial, Helvetica, sans-serif; font-size: 8.5pt; color: #555; margin-top: 1mm; } .doc-date { text-align: right; font-size: 10.5pt; margin-bottom: 16mm; } .doc-title { font-family: Arial, Helvetica, sans-serif; font-size: 14pt; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 3mm; } .title-underline { display: block; width: 68%; border: none; border-top: 2px solid #000; margin: 0 auto 10mm; } .body-text { line-height: 1.9; text-align: justify; margin: 3.5mm 0; } .signature-block { margin-top: 14mm; text-align: right; line-height: 2; } .footer-rule { position: absolute; bottom: 20mm; left: 22mm; right: 22mm; height: 1px; background: #ccc; } .footer { position: absolute; bottom: 6mm; left: 22mm; right: 22mm; font-family: Arial, Helvetica, sans-serif; font-size: 7pt; color: #888; text-align: center; line-height: 1.7; }</style></head><body><div class="page"><div class="header"><div><div class="arx-logo-text">ARX</div><div class="arx-tagline">S M A R T &nbsp; M I N D S</div></div><div class="company-block"><div class="company-name-hdr">ARX Tunisie</div><div class="company-sub">Bureau d''etudes en Genie Civil</div></div></div><div class="doc-date">{{employee.city}}, le {{document.date}}</div><div class="doc-title">Attestation de Travail</div><hr class="title-underline"><p class="body-text">Je soussigne(e), <strong>{{company.dgName}}</strong>, titulaire de la CIN n&deg; <strong>{{company.dgCin}}</strong> delivree a {{company.dgCinCity}} le {{company.dgCinDate}}, agissant en qualite de <strong>{{company.dgTitle}}</strong> de la societe <strong>ARX Tunisie</strong>,</p><p class="body-text">Atteste par la presente que <strong>{{employee.civilite}} {{employee.fullName}}</strong>, titulaire de la CIN n&deg; <strong>{{employee.cin}}</strong> delivree a {{employee.cinCity}} le {{employee.cinDate}}, occupe le poste de <strong>{{employee.position}}</strong> au sein de notre societe, et ce depuis le <strong>{{employee.startDateMoisAn}}</strong> dans le cadre d''un contrat de travail a duree <strong>{{employee.contractDuration}}</strong>.</p><p class="body-text">Cette attestation est delivree a l''interesse(e) pour servir et valoir ce que de droit.</p><div class="signature-block"><p><strong>ARX Tunisie</strong></p><p>{{company.dgTitle}}</p><br><br><p><em>{{company.dgName}}</em></p></div><div class="footer-rule"></div><div class="footer"><div><strong>ARX Tunisie</strong> &mdash; Bureau d''etudes en genie civil</div><div>Siege Social : 7 Avenue de Paris, BOUMHEL EL BASSATINE, 2097, GOUVERNORAT DE BEN AROUS</div><div style="margin-top:1.5mm;">Page 1 sur 1 &nbsp;&nbsp;|&nbsp;&nbsp; Ref : {{document.ref}} &nbsp;&nbsp;|&nbsp;&nbsp; Code verif. : {{document.verificationCode}}</div></div></div></body></html>',
    N'["employee.city","employee.civilite","employee.fullName","employee.cin","employee.cinCity","employee.cinDate","employee.position","employee.startDateMoisAn","employee.contractDuration","company.dgName","company.dgTitle","company.dgCin","company.dgCinCity","company.dgCinDate","document.date","document.ref","document.verificationCode"]',
    N'A4', 1, SYSDATETIMEOFFSET()
FROM [dbo].[pays] p
WHERE NOT EXISTS (
    SELECT 1 FROM [dbo].[document_templates] dt
    WHERE dt.pays_id = p.id AND dt.name = N'Attestation de Travail'
);
GO

-- ── 2. Attestation de Salaire ─────────────────────────────────────────────
INSERT INTO [dbo].[document_templates]
    ([pays_id],[category],[name],[description],[html_content],[variables],[page_size],[is_active],[created_at])
SELECT
    p.id,
    N'ATTESTATION',
    N'Attestation de Salaire',
    N'Attestation de salaire avec montant brut annuel et duree de contrat',
    N'<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { font-family: Georgia, ''Times New Roman'', Times, serif; font-size: 11pt; color: #000; } .page { width: 210mm; min-height: 297mm; padding: 18mm 22mm 30mm; position: relative; background: #fff; } .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12mm; } .arx-logo-text { font-family: Arial, Helvetica, sans-serif; font-size: 30pt; font-weight: 900; color: #1e3a5f; line-height: 1; letter-spacing: -1px; } .arx-tagline { font-family: Arial, Helvetica, sans-serif; font-size: 6.5pt; color: #666; letter-spacing: 4px; margin-top: 2mm; } .company-block { text-align: right; } .company-name-hdr { font-family: Arial, Helvetica, sans-serif; font-size: 11pt; font-weight: bold; color: #1e3a5f; } .company-sub { font-family: Arial, Helvetica, sans-serif; font-size: 8.5pt; color: #555; margin-top: 1mm; } .doc-date { text-align: right; font-size: 10.5pt; margin-bottom: 16mm; } .doc-title { font-family: Arial, Helvetica, sans-serif; font-size: 14pt; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 3mm; } .title-underline { display: block; width: 68%; border: none; border-top: 2px solid #000; margin: 0 auto 10mm; } .body-text { line-height: 1.9; text-align: justify; margin: 3.5mm 0; } .signature-block { margin-top: 14mm; text-align: right; line-height: 2; } .footer-rule { position: absolute; bottom: 20mm; left: 22mm; right: 22mm; height: 1px; background: #ccc; } .footer { position: absolute; bottom: 6mm; left: 22mm; right: 22mm; font-family: Arial, Helvetica, sans-serif; font-size: 7pt; color: #888; text-align: center; line-height: 1.7; }</style></head><body><div class="page"><div class="header"><div><div class="arx-logo-text">ARX</div><div class="arx-tagline">S M A R T &nbsp; M I N D S</div></div><div class="company-block"><div class="company-name-hdr">ARX Tunisie</div><div class="company-sub">Bureau d''etudes en Genie Civil</div></div></div><div class="doc-date">{{employee.city}}, le {{document.date}}</div><div class="doc-title">Attestation de Salaire</div><hr class="title-underline"><p class="body-text">Je soussigne(e), <strong>{{company.dgName}}</strong>, titulaire de la CIN n&deg; <strong>{{company.dgCin}}</strong> delivree a {{company.dgCinCity}} le {{company.dgCinDate}}, agissant en qualite de <strong>{{company.dgTitle}}</strong> de la societe <strong>ARX Tunisie</strong> ;</p><p class="body-text">Atteste par la presente que <strong>{{employee.civilite}} {{employee.fullName}}</strong>, titulaire de la CIN n&deg; <strong>{{employee.cin}}</strong> delivree a {{employee.cinCity}} le {{employee.cinDate}}, et employe(e) au sein de notre societe depuis le <strong>{{employee.startDateMoisAn}}</strong>, percoit un Salaire Annuel Brut estime a <strong>{{employee.salaireBrutAnnuel}} Dinars Tunisiens (TND)</strong> soit <strong>{{employee.salaireBrutAnnuelEnLettres}}</strong>.</p><p class="body-text">Cette attestation est delivree a l''interesse(e) pour servir et valoir ce que de droit.</p><div class="signature-block"><p><strong>{{company.dgTitle}}</strong></p><br><br><p><em>{{company.dgName}}</em></p></div><div class="footer-rule"></div><div class="footer"><div><strong>ARX Tunisie</strong> &mdash; Bureau d''etudes en Genie Civil</div><div>Siege Social : 7 Avenue de Paris, BOUMHEL EL BASSATINE, 2097, GOUVERNORAT DE BEN AROUS</div><div style="margin-top:1.5mm;">Page 1 sur 1 &nbsp;&nbsp;|&nbsp;&nbsp; Ref : {{document.ref}} &nbsp;&nbsp;|&nbsp;&nbsp; Code verif. : {{document.verificationCode}}</div></div></div></body></html>',
    N'["employee.city","employee.civilite","employee.fullName","employee.cin","employee.cinCity","employee.cinDate","employee.startDateMoisAn","employee.salaireBrutAnnuel","employee.salaireBrutAnnuelEnLettres","company.dgName","company.dgTitle","company.dgCin","company.dgCinCity","company.dgCinDate","document.date","document.ref","document.verificationCode"]',
    N'A4', 1, SYSDATETIMEOFFSET()
FROM [dbo].[pays] p
WHERE NOT EXISTS (
    SELECT 1 FROM [dbo].[document_templates] dt
    WHERE dt.pays_id = p.id AND dt.name = N'Attestation de Salaire'
);
GO

-- ── 3. Attestation de Non-Benefice de Pret ────────────────────────────────
-- Structure: employee is the first-person declarant; direction signs.
INSERT INTO [dbo].[document_templates]
    ([pays_id],[category],[name],[description],[html_content],[variables],[page_size],[is_active],[created_at])
SELECT
    p.id,
    N'ATTESTATION',
    N'Attestation de Non-Benefice de Pret',
    N'Attestation sur l''honneur de l''employe attestant l''absence de pret en cours',
    N'<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { font-family: Georgia, ''Times New Roman'', Times, serif; font-size: 11pt; color: #000; } .page { width: 210mm; min-height: 297mm; padding: 18mm 22mm 30mm; position: relative; background: #fff; } .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12mm; } .arx-logo-text { font-family: Arial, Helvetica, sans-serif; font-size: 30pt; font-weight: 900; color: #1e3a5f; line-height: 1; letter-spacing: -1px; } .arx-tagline { font-family: Arial, Helvetica, sans-serif; font-size: 6.5pt; color: #666; letter-spacing: 4px; margin-top: 2mm; } .company-block { text-align: right; } .company-name-hdr { font-family: Arial, Helvetica, sans-serif; font-size: 11pt; font-weight: bold; color: #1e3a5f; } .company-sub { font-family: Arial, Helvetica, sans-serif; font-size: 8.5pt; color: #555; margin-top: 1mm; } .doc-date { text-align: right; font-size: 10.5pt; margin-bottom: 16mm; } .doc-title { font-family: Arial, Helvetica, sans-serif; font-size: 14pt; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 3mm; } .title-underline { display: block; width: 68%; border: none; border-top: 2px solid #000; margin: 0 auto 10mm; } .body-text { line-height: 1.9; text-align: justify; margin: 3.5mm 0; } .signature-block { margin-top: 14mm; text-align: right; line-height: 2; } .footer-rule { position: absolute; bottom: 20mm; left: 22mm; right: 22mm; height: 1px; background: #ccc; } .footer { position: absolute; bottom: 6mm; left: 22mm; right: 22mm; font-family: Arial, Helvetica, sans-serif; font-size: 7pt; color: #888; text-align: center; line-height: 1.7; }</style></head><body><div class="page"><div class="header"><div><div class="arx-logo-text">ARX</div><div class="arx-tagline">S M A R T &nbsp; M I N D S</div></div><div class="company-block"><div class="company-name-hdr">ARX Tunisie</div><div class="company-sub">Bureau d''etudes en genie civil</div></div></div><div class="doc-date">{{employee.city}}, le {{document.date}}</div><div class="doc-title">Attestation de Non-Benefice de Pret</div><hr class="title-underline"><p class="body-text">Je soussigne(e), <strong>{{employee.civilite}} {{employee.fullName}}</strong>, titulaire de la CIN n&deg; <strong>{{employee.cin}}</strong> delivree a {{employee.cinCity}} le {{employee.cinDate}}, employe(e) au sein de la societe <strong>ARX Tunisie</strong> (Bureau d''etudes en genie civil) et domicilie(e) a {{employee.city}},</p><p class="body-text">Atteste par la presente, de maniere libre et solennelle, ne beneficier d''aucun pret, credit en cours, ni d''aucune avance financiere de quelque nature que ce soit aupres de mon employeur, la societe <strong>ARX Tunisie</strong>, a ce jour.</p><p class="body-text">Cette attestation est delivree a l''interesse(e) pour servir et valoir ce que de droit.</p><div class="signature-block"><p><strong>Pour ARX Tunisie</strong></p><p>{{company.dgTitle}}</p><br><br><p><em>{{company.dgName}}</em></p></div><div class="footer-rule"></div><div class="footer"><div><strong>ARX Tunisie</strong> &mdash; Bureau d''etudes en genie civil</div><div>Siege Social : 7 Avenue de Paris, BOUMHEL EL BASSATINE, 2097, GOUVERNORAT DE BEN AROUS</div><div style="margin-top:1.5mm;">Page 1 sur 1 &nbsp;&nbsp;|&nbsp;&nbsp; Ref : {{document.ref}} &nbsp;&nbsp;|&nbsp;&nbsp; Code verif. : {{document.verificationCode}}</div></div></div></body></html>',
    N'["employee.city","employee.civilite","employee.fullName","employee.cin","employee.cinCity","employee.cinDate","company.dgName","company.dgTitle","document.date","document.ref","document.verificationCode"]',
    N'A4', 1, SYSDATETIMEOFFSET()
FROM [dbo].[pays] p
WHERE NOT EXISTS (
    SELECT 1 FROM [dbo].[document_templates] dt
    WHERE dt.pays_id = p.id AND dt.name = N'Attestation de Non-Benefice de Pret'
);
GO

-- ── 4. Attestation de Titularisation ─────────────────────────────────────
INSERT INTO [dbo].[document_templates]
    ([pays_id],[category],[name],[description],[html_content],[variables],[page_size],[is_active],[created_at])
SELECT
    p.id,
    N'ATTESTATION',
    N'Attestation de Titularisation',
    N'Attestation de titularisation en contrat a duree indeterminee',
    N'<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { font-family: Georgia, ''Times New Roman'', Times, serif; font-size: 11pt; color: #000; } .page { width: 210mm; min-height: 297mm; padding: 18mm 22mm 30mm; position: relative; background: #fff; } .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12mm; } .arx-logo-text { font-family: Arial, Helvetica, sans-serif; font-size: 30pt; font-weight: 900; color: #1e3a5f; line-height: 1; letter-spacing: -1px; } .arx-tagline { font-family: Arial, Helvetica, sans-serif; font-size: 6.5pt; color: #666; letter-spacing: 4px; margin-top: 2mm; } .company-block { text-align: right; } .company-name-hdr { font-family: Arial, Helvetica, sans-serif; font-size: 11pt; font-weight: bold; color: #1e3a5f; } .company-sub { font-family: Arial, Helvetica, sans-serif; font-size: 8.5pt; color: #555; margin-top: 1mm; } .doc-date { text-align: right; font-size: 10.5pt; margin-bottom: 16mm; } .doc-title { font-family: Arial, Helvetica, sans-serif; font-size: 14pt; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 3mm; } .title-underline { display: block; width: 68%; border: none; border-top: 2px solid #000; margin: 0 auto 10mm; } .body-text { line-height: 1.9; text-align: justify; margin: 3.5mm 0; } .signature-block { margin-top: 14mm; text-align: right; line-height: 2; } .footer-rule { position: absolute; bottom: 20mm; left: 22mm; right: 22mm; height: 1px; background: #ccc; } .footer { position: absolute; bottom: 6mm; left: 22mm; right: 22mm; font-family: Arial, Helvetica, sans-serif; font-size: 7pt; color: #888; text-align: center; line-height: 1.7; }</style></head><body><div class="page"><div class="header"><div><div class="arx-logo-text">ARX</div><div class="arx-tagline">S M A R T &nbsp; M I N D S</div></div><div class="company-block"><div class="company-name-hdr">ARX Tunisie</div><div class="company-sub">Bureau d''etudes en Genie Civil</div></div></div><div class="doc-date">{{employee.city}}, le {{document.date}}</div><div class="doc-title">Attestation de Titularisation</div><hr class="title-underline"><p class="body-text">Je soussigne(e), <strong>{{company.dgName}}</strong>, titulaire de la CIN n&deg; <strong>{{company.dgCin}}</strong> delivree a {{company.dgCinCity}} le {{company.dgCinDate}}, agissant en qualite de <strong>{{company.dgTitle}}</strong> de la societe <strong>ARX Tunisie</strong>,</p><p class="body-text">Atteste par la presente que <strong>{{employee.civilite}} {{employee.fullName}}</strong>, titulaire de la CIN n&deg; <strong>{{employee.cin}}</strong> delivree a {{employee.cinCity}} le {{employee.cinDate}}, a ete titularise(e) au poste de <strong>{{employee.position}}</strong> au sein de notre societe a compter du <strong>{{employee.titularisationDate}}</strong>.</p><p class="body-text">{{employee.civilite}} {{employee.fullName}} beneficie a ce titre d''un contrat de travail a duree indeterminee conformement a la legislation sociale en vigueur.</p><p class="body-text">Cette attestation est delivree a l''interesse(e) pour servir et valoir ce que de droit.</p><div class="signature-block"><p><strong>ARX Tunisie</strong></p><p>{{company.dgTitle}}</p><br><br><p><em>{{company.dgName}}</em></p></div><div class="footer-rule"></div><div class="footer"><div><strong>ARX Tunisie</strong> &mdash; Bureau d''etudes en genie civil</div><div>Siege Social : 7 Avenue de Paris, BOUMHEL EL BASSATINE, 2097, GOUVERNORAT DE BEN AROUS</div><div style="margin-top:1.5mm;">Page 1 sur 1 &nbsp;&nbsp;|&nbsp;&nbsp; Ref : {{document.ref}} &nbsp;&nbsp;|&nbsp;&nbsp; Code verif. : {{document.verificationCode}}</div></div></div></body></html>',
    N'["employee.city","employee.civilite","employee.fullName","employee.cin","employee.cinCity","employee.cinDate","employee.position","employee.titularisationDate","company.dgName","company.dgTitle","company.dgCin","company.dgCinCity","company.dgCinDate","document.date","document.ref","document.verificationCode"]',
    N'A4', 1, SYSDATETIMEOFFSET()
FROM [dbo].[pays] p
WHERE NOT EXISTS (
    SELECT 1 FROM [dbo].[document_templates] dt
    WHERE dt.pays_id = p.id AND dt.name = N'Attestation de Titularisation'
);
GO

-- ── 5. Attestation de Domiciliation de Salaire ───────────────────────────
INSERT INTO [dbo].[document_templates]
    ([pays_id],[category],[name],[description],[html_content],[variables],[page_size],[is_active],[created_at])
SELECT
    p.id,
    N'ATTESTATION',
    N'Attestation de Domiciliation de Salaire',
    N'Attestation de domiciliation bancaire du salaire',
    N'<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { font-family: Georgia, ''Times New Roman'', Times, serif; font-size: 11pt; color: #000; } .page { width: 210mm; min-height: 297mm; padding: 18mm 22mm 30mm; position: relative; background: #fff; } .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12mm; } .arx-logo-text { font-family: Arial, Helvetica, sans-serif; font-size: 30pt; font-weight: 900; color: #1e3a5f; line-height: 1; letter-spacing: -1px; } .arx-tagline { font-family: Arial, Helvetica, sans-serif; font-size: 6.5pt; color: #666; letter-spacing: 4px; margin-top: 2mm; } .company-block { text-align: right; } .company-name-hdr { font-family: Arial, Helvetica, sans-serif; font-size: 11pt; font-weight: bold; color: #1e3a5f; } .company-sub { font-family: Arial, Helvetica, sans-serif; font-size: 8.5pt; color: #555; margin-top: 1mm; } .doc-date { text-align: right; font-size: 10.5pt; margin-bottom: 16mm; } .doc-title { font-family: Arial, Helvetica, sans-serif; font-size: 14pt; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 3mm; } .title-underline { display: block; width: 68%; border: none; border-top: 2px solid #000; margin: 0 auto 10mm; } .body-text { line-height: 1.9; text-align: justify; margin: 3.5mm 0; } .bank-block { margin: 4mm 0 4mm 28mm; line-height: 2.2; } .bank-row { display: flex; gap: 6mm; align-items: baseline; } .bank-label { font-weight: bold; min-width: 18mm; } .signature-block { margin-top: 14mm; text-align: right; line-height: 2; } .footer-rule { position: absolute; bottom: 20mm; left: 22mm; right: 22mm; height: 1px; background: #ccc; } .footer { position: absolute; bottom: 6mm; left: 22mm; right: 22mm; font-family: Arial, Helvetica, sans-serif; font-size: 7pt; color: #888; text-align: center; line-height: 1.7; }</style></head><body><div class="page"><div class="header"><div><div class="arx-logo-text">ARX</div><div class="arx-tagline">S M A R T &nbsp; M I N D S</div></div><div class="company-block"><div class="company-name-hdr">ARX Tunisie</div><div class="company-sub">Bureau d''etudes en Genie Civil</div></div></div><div class="doc-date">{{employee.city}}, le {{document.date}}</div><div class="doc-title">Attestation de Domiciliation de Salaire</div><hr class="title-underline"><p class="body-text">Je soussigne(e), <strong>{{company.dgName}}</strong>, titulaire de la CIN n&deg; <strong>{{company.dgCin}}</strong> delivree a {{company.dgCinCity}} le {{company.dgCinDate}}, agissant en qualite de <strong>{{company.dgTitle}}</strong> de la societe <strong>ARX Tunisie</strong>,</p><p class="body-text">Atteste par la presente que le salaire de <strong>{{employee.civilite}} {{employee.fullName}}</strong>, occupant le poste de <strong>{{employee.position}}</strong> au sein de notre societe depuis le <strong>{{employee.startDate}}</strong>, est domicilie a la banque suivante :</p><div class="bank-block"><div class="bank-row"><span class="bank-label">Banque :</span><span>{{employee.bank}}</span></div><div class="bank-row"><span class="bank-label">RIB :</span><span>{{employee.rib}}</span></div><div class="bank-row"><span class="bank-label">IBAN :</span><span>{{employee.iban}}</span></div></div><p class="body-text">Le virement du salaire est effectue mensuellement sur ce compte.</p><p class="body-text">Cette attestation est delivree a la demande de l''interesse(e) pour servir et valoir ce que de droit.</p><div class="signature-block"><p><strong>ARX Tunisie</strong></p><p>{{company.dgTitle}}</p><br><br><p><em>{{company.dgName}}</em></p></div><div class="footer-rule"></div><div class="footer"><div><strong>ARX Tunisie</strong> &mdash; Bureau d''etudes en genie civil</div><div>Siege Social : 7 Avenue de Paris, BOUMHEL EL BASSATINE, 2097, GOUVERNORAT DE BEN AROUS</div><div style="margin-top:1.5mm;">Page 1 sur 1 &nbsp;&nbsp;|&nbsp;&nbsp; Ref : {{document.ref}} &nbsp;&nbsp;|&nbsp;&nbsp; Code verif. : {{document.verificationCode}}</div></div></div></body></html>',
    N'["employee.city","employee.civilite","employee.fullName","employee.position","employee.startDate","employee.bank","employee.rib","employee.iban","company.dgName","company.dgTitle","company.dgCin","company.dgCinCity","company.dgCinDate","document.date","document.ref","document.verificationCode"]',
    N'A4', 1, SYSDATETIMEOFFSET()
FROM [dbo].[pays] p
WHERE NOT EXISTS (
    SELECT 1 FROM [dbo].[document_templates] dt
    WHERE dt.pays_id = p.id AND dt.name = N'Attestation de Domiciliation de Salaire'
);
GO

-- ── 6. Lettre d'Invitation ARX France ─────────────────────────────────────
-- Sender info and trip details are provided via extraCtx at render time:
--   sender.name, sender.title, sender.address, sender.city
--   employee.birthDate, employee.birthCity, employee.passportNumber
--   trip.startDate, trip.endDate, trip.hotel
INSERT INTO [dbo].[document_templates]
    ([pays_id],[category],[name],[description],[html_content],[variables],[page_size],[is_active],[created_at])
SELECT
    p.id,
    N'ATTESTATION',
    N'Lettre d''Invitation ARX France',
    N'Lettre d''invitation professionnelle pour visa France (Consulat de France a Tunis)',
    N'<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { font-family: Georgia, ''Times New Roman'', Times, serif; font-size: 11pt; color: #000; } .page { width: 210mm; min-height: 297mm; padding: 18mm 22mm 30mm; position: relative; background: #fff; } .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 14mm; } .arx-logo-text { font-family: Arial, Helvetica, sans-serif; font-size: 30pt; font-weight: 900; color: #1e3a5f; line-height: 1; letter-spacing: -1px; } .arx-tagline { font-family: Arial, Helvetica, sans-serif; font-size: 6.5pt; color: #666; letter-spacing: 4px; margin-top: 2mm; } .sender-block { margin-bottom: 8mm; font-size: 10.5pt; line-height: 1.6; } .date-recipient-row { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 10mm; } .doc-date { font-size: 10.5pt; } .recipient-block { text-align: left; font-size: 10.5pt; line-height: 1.7; } .subject-line { margin: 8mm 0 10mm; font-size: 10.5pt; line-height: 1.6; } .salutation { margin-bottom: 6mm; font-size: 10.5pt; } .body-text { line-height: 1.9; text-align: justify; margin: 4mm 0; font-size: 10.5pt; } .signature-block { margin-top: 14mm; text-align: left; line-height: 2; font-size: 10.5pt; } .footer-rule { position: absolute; bottom: 20mm; left: 22mm; right: 22mm; height: 1px; background: #ccc; } .footer { position: absolute; bottom: 6mm; left: 22mm; right: 22mm; font-family: Arial, Helvetica, sans-serif; font-size: 7pt; color: #888; text-align: center; line-height: 1.7; }</style></head><body><div class="page"><div class="header"><div><div class="arx-logo-text">ARX</div><div class="arx-tagline">S M A R T &nbsp; M I N D S</div></div></div><div class="sender-block"><strong>{{sender.name}}</strong><br>{{sender.title}}<br>{{sender.address}}<br>{{sender.city}}</div><div class="date-recipient-row"><div class="doc-date">{{employee.city}}, le {{document.date}}</div><div class="recipient-block"><strong>Consulat General de France a Tunis</strong><br>Avenue Habib Bourguiba,<br>Tunis, Tunisie</div></div><div class="subject-line"><strong>Objet :</strong> Invitation professionnelle pour une reunion de chantier en presentiel<br><strong>Copie :</strong> ARX Tunisie</div><p class="salutation">Monsieur le Consul,</p><p class="body-text">Agissant en qualite de <strong>{{sender.title}}</strong> de la societe <strong>Arx France</strong>, je vous informe avoir l''intention d''inviter en France le ressortissant etranger ci-apres designe : <strong>{{employee.civilite}} {{employee.fullName}}</strong>, ne(e) le <strong>{{employee.birthDate}}</strong> a <strong>{{employee.birthCity}}</strong>, detenteur(trice) du passeport n&deg; <strong>{{employee.passportNumber}}</strong>, residant actuellement en TUNISIE, {{employee.city}} Tunisie et exercant la profession de <strong>{{employee.position}}</strong>.</p><p class="body-text">Cette invitation intervenant dans un cadre strictement professionnel est prevue pour une duree de 30 jours, du <strong>{{trip.startDate}}</strong> au <strong>{{trip.endDate}}</strong>. Elle a pour objectif la realisation et le suivi des etudes d''execution pour le projet <strong>Ligne 15 Grand Paris</strong> dans le cadre de prestations d''etudes realisees par ARX Tunisie, sur le projet pour le compte de Arx France.</p><p class="body-text">La presence de <strong>{{employee.civilite}} {{employee.fullName}}</strong> est requise pour coordonner les etudes, assister aux reunions de chantier et a la reunion d''Audit avec le client d''Arx France. Cette mission d''etudes ne peut etre effectuee a distance ni etre reportee dans le temps.</p><p class="body-text">Pendant la duree de son sejour, <strong>{{employee.civilite}} {{employee.fullName}}</strong> residera dans l''hotel <strong>{{trip.hotel}}</strong>.</p><p class="body-text">Les frais inherents au sejour en France de <strong>{{employee.civilite}} {{employee.fullName}}</strong> seront integralement pris en charge par son employeur, la societe <strong>ARX Tunisie</strong> domiciliee au 7, Avenue de Paris, BOUMHEL EL BASSATINE, TUNISIE.</p><p class="body-text">Je reste a votre entiere disposition pour vous fournir toute precision utile et vous prie de croire, Monsieur le Consul, en l''assurance de ma respectueuse consideration.</p><div class="signature-block"><strong>{{sender.name}}</strong><br>{{sender.title}}</div><div class="footer-rule"></div><div class="footer"><div><strong>ARX Tunisie</strong> &mdash; Bureau d''etudes en genie civil</div><div>Siege Social : 7 Avenue de Paris, BOUMHEL EL BASSATINE, 2097, GOUVERNORAT DE BEN AROUS</div><div style="margin-top:1.5mm;">Page 1 sur 1</div></div></div></body></html>',
    N'["employee.city","employee.civilite","employee.fullName","employee.position","employee.birthDate","employee.birthCity","employee.passportNumber","sender.name","sender.title","sender.address","sender.city","trip.startDate","trip.endDate","trip.hotel","document.date"]',
    N'A4', 1, SYSDATETIMEOFFSET()
FROM [dbo].[pays] p
WHERE NOT EXISTS (
    SELECT 1 FROM [dbo].[document_templates] dt
    WHERE dt.pays_id = p.id AND dt.name = N'Lettre d''Invitation ARX France'
);
GO
